import{j as e}from"./index-BkbKlLLp.js";import{L as t,l as a}from"./LocationPage-BcpbFCac.js";import"./Breadcrumbs-DYouPYGL.js";import"./building-2-BvL7sohP.js";import"./info-0dsNs12q.js";import"./circle-help-ChY-WUzv.js";const n={path:"/locations/united-states",h1:"Software and AI Development for Businesses in the United States",valueProp:"An India-based software and AI development partner for United States businesses — engaged remotely, scoped in writing, and demonstrated to you every cycle.",heroHighlights:["Built and delivered from our office in Indore, India, for clients across the United States","A recurring overlap window agreed with you before development starts","Scope, assumptions and exclusions written down before the first sprint","Source code, designs and cloud accounts are yours throughout and at handover"],intro:["Most United States enquiries reach us the same way. There is a product or an internal system that has to exist, the in-house engineers are already committed to something else, and recruiting for the gap domestically would consume a quarter the business does not have. SCS Softwares takes that build on as an outside engineering team, working from Indore, India.","An arrangement like that only works when the boundaries are explicit. Before development begins we write down what is being built, what the estimate assumes, and what is deliberately excluded. Then we demonstrate against that document every cycle, so the distance between us shows up as scheduled meetings rather than as a surprise at the end of the project.","The engineering itself is what we do everywhere: custom applications, mobile and web products, subscription platforms, modernization of a system already carrying live traffic, and AI features built into those products with a person reviewing what the model produces. What a United States engagement changes is the logistics around it — meeting times, written handover, and the contract, invoicing and data questions settled before anyone writes code."],disclosure:{title:"Where SCS Softwares actually is",body:"SCS Softwares operates from Indore, Madhya Pradesh, India. Every United States project is delivered remotely from that office, by the same engineers who build for our clients elsewhere.",points:["We do not maintain a local office, a registered US entity or a local phone line anywhere in the United States, and we do not present one.","Services are delivered remotely: discovery, design review, demonstrations and sign-off all happen online, in scheduled calls.","Our address, telephone number and company registration are Indian, and they appear on every proposal, contract and invoice.","We employ no staff in the United States, and we make no claim to US employment, sponsorship or on-site presence.","We give no legal or tax advice for any US jurisdiction. Your own counsel keeps that role, and we work to whatever they require of us."]},concerns:{eyebrow:"Before you sign",heading:"The questions US buyers ask us first",intro:"None of these are unreasonable — they are the questions we would ask an overseas vendor too. So here are the answers in advance, rather than three calls in.",items:[{title:"Who is accountable when something breaks",body:"One named point of contact, plus the engineers actually assigned to your build rather than a rotating pool. Escalation is written into the engagement, so there is a person to reach and an agreed response path instead of a shared inbox."},{title:"Who owns the code and the accounts",body:"You do, from the first commit. Repositories, designs, cloud accounts and credentials are created in your name where possible and handed over in full at the end. We hold nothing back that would make leaving us expensive."},{title:"How the time-zone gap is actually handled",body:"Indian Standard Time runs nine and a half to ten and a half hours ahead of US Eastern, depending on daylight saving. We agree a recurring overlap window with you before the project starts rather than implying all-day coverage we have not committed to."},{title:"Where the data will live and who can reach it",body:"Hosting region, who on our side holds access, what may leave your environment and how credentials are shared are all decided during discovery and written into the agreement, before any access is granted."},{title:"Whether the estimate will hold",body:"An estimate is a range built on a written scope, and we state the assumptions it rests on. When a change request lands, it is re-estimated in writing and approved before it is built, rather than quietly absorbed and billed later."},{title:"Whether AI output can be trusted in production",body:"Not on its own. Wherever a model touches a customer, a payment or a stored record, we build a review step and a fallback path, and we write down what the system is not allowed to decide by itself."}]},services:{eyebrow:"Where US projects usually start",heading:"The services behind a United States engagement",intro:"These pages describe the work itself, without a regional angle. The market page you are reading covers how we run it with you from India.",items:[{path:"/services/custom-software-development",label:"Custom Software Development",blurb:"The usual entry point for a US engagement: an application built for one business process, replacing the spreadsheet-and-email arrangement it grew out of."},{path:"/services/mobile-app-development",label:"Mobile App Development",blurb:"iOS and Android builds, including the parts US launches actually stall on — store review, payments, push notifications and offline behaviour."},{path:"/services/web-application-development",label:"Web Application Development",blurb:"Customer portals, dashboards, marketplaces and booking flows, with the APIs, roles and admin tooling that have to exist behind them."},{path:"/services/saas-development",label:"SaaS Development",blurb:"Subscription products from first release to multi-tenant platform: plans, billing, roles, usage limits and the architecture underneath them."},{path:"/services/software-modernization",label:"Software Modernization",blurb:"For the system that already runs the business and cannot be switched off: assessment first, then incremental change against live traffic."},{path:"/services/ai-development",label:"AI Development",blurb:"Assistants, retrieval over your own content and structured AI workflows, with the monitoring, cost controls and review steps around them."},{path:"/services/ai-voice-agent-development",label:"AI Voice Agent Development",blurb:"Real-time spoken conversation inside your product, with interruption handling, a defined tool set and a documented escalation to your team."},{path:"/services/ai-video-consultation-agents",label:"AI Video Consultation Agents",blurb:"An avatar-led consultation room that gathers requirements or intake details and produces a structured summary a person reviews afterwards."},{path:"/services/ai-automation-integration",label:"AI Automation & Integration",blurb:"Document processing, structured extraction and workflow automation wired into the systems you already run, with approvals and an audit trail."}]},projectTypes:{eyebrow:"Project fit",heading:"What US clients bring us",intro:"A remote engineering team is a good fit for some of these and a poor fit for others. The list below is the shape of work that has gone well.",items:[{title:"A first product release with a fixed window",body:"A funded idea that needs to be in front of real users by a date. We scope a first release deliberately narrow, ship it, and treat everything else as a second phase rather than padding the first."},{title:"An internal tool that outgrew its spreadsheet",body:"Operations running on shared sheets, form responses and manual copying. The build replaces the copying with a system of record, permissions and an audit trail people can actually be held to."},{title:"A platform that needs a second engineering team",body:"Your engineers stay on the core product while we take a bounded piece — an integration, a portal, a reporting surface — with its own scope, branch discipline and review gate."},{title:"An AI feature inside an existing product",body:"The product works; the AI feature on the roadmap keeps slipping. We build it as software — grounded in your content, bounded by defined tools, reviewed by a person where the answer matters."},{title:"A system nobody wants to touch any more",body:"An application still carrying business but built by someone who left. We assess it first, agree what is worth keeping, and change it incrementally instead of proposing a rewrite by reflex."},{title:"Integration work between systems that never spoke",body:"A CRM, a billing platform and a warehouse system reconciled by hand every week. We build the API layer, the mapping and the failure handling so the reconciliation stops being a job."}]},collaboration:{eyebrow:"How it runs",heading:"A United States engagement, stage by stage",intro:"Every stage below has a written output, because a written output is what survives a ten-hour gap between two working days.",steps:[{title:"First call and problem framing",body:"A scheduled call in your morning, our evening. We are trying to establish what the system has to do and what would make the project a failure — not to present slides.",points:["Booked at a time inside your business day","Recorded notes shared afterwards, so nothing rests on memory","An early view on whether we are the wrong fit for this build"]},{title:"Remote discovery and written scope",body:"Requirements, integrations, permissions and edge cases documented into one scope you can read, argue with and approve before any estimate is treated as real.",points:["Features, assumptions and exclusions in the same document","Data-location, access and privacy requirements captured here, not later","An estimate expressed as a range, with the assumptions it depends on"]},{title:"Commercials, access and kick-off",body:"Contract, invoicing arrangement, communication schedule and the overlap window are all agreed in writing before the first sprint opens.",points:["Agreement, payment schedule and invoicing route settled up front","A recurring meeting slot fixed inside your working day","Repository, environment and credential handling agreed before access is granted"]},{title:"Build cycles with milestone demonstrations",body:"Work lands in cycles, and each one ends in a build you open yourself. Progress is something you click, not a percentage in a status report.",points:["A deployed environment updated every cycle","A live demonstration and written notes against the agreed scope","Change requests re-estimated and approved in writing before they are built"]},{title:"Release, handover and ongoing support",body:"Release is a checklist, not an event. Afterwards you decide whether we stay on for maintenance or hand everything over and step away.",points:["Store submissions, deployment and rollback path prepared in advance","Repositories, designs, accounts and documentation transferred to you","A support arrangement only if you want one — there is no lock-in either way"]}]},communication:{eyebrow:"Working hours",heading:"Overlap, meetings and the written trail",intro:"The honest version: our team works Indian hours, and we shift part of the day to meet yours. What that shift looks like is agreed with you rather than advertised in advance.",points:["Indian Standard Time is nine and a half to ten and a half hours ahead of US Eastern, and twelve and a half to thirteen and a half hours ahead of US Pacific.","We agree one recurring overlap window per engagement, in writing, and staff it for the people on your project.","We do not offer round-the-clock coverage and we do not claim a support desk that answers at any hour of the US day.","Demonstrations, design reviews and approvals are booked inside your working day, not ours.","Written updates land before your morning, so a decision is not blocked waiting for our next shift.","Anything urgent follows an escalation route agreed at kick-off, with a named contact rather than a shared queue."],note:"If a project genuinely needs coverage during US night hours, say so during discovery. It changes the staffing and therefore the estimate, and we would rather price it honestly than promise it and miss."},security:{eyebrow:"Security and privacy",heading:"How data, access and privacy questions are handled",intro:"A remote team is an access decision as much as an engineering one. These are the parts we agree in writing before anyone connects to anything.",points:["Hosting region and data residency are chosen with you during discovery and recorded in the agreement.","Access is granted per person and per environment, and revoked when someone leaves the project.","Production data is not copied to developer machines; test data is generated or masked instead.","Credentials move through a secret manager or your own vault, never through chat or email.","Confidentiality and IP assignment are covered by the signed agreement before development starts.","Dependency updates, security patching and backup restore tests are part of the maintenance arrangement, not an extra."],note:"We hold no security certification and we do not describe ourselves as HIPAA, SOC 2 or PCI compliant. If your project sits inside one of those frameworks, tell us during discovery: we will build to the controls your compliance team specifies and let them verify the result, rather than claiming a status we cannot evidence."},oversight:{title:"Human review over AI output",body:"AI features are probabilistic, and a US buyer is usually the one carrying the consequence when one is wrong. So we design the review step at the same time as the feature.",points:["A person approves anything that changes money, contracts or a customer record.","The system is built to say it does not know, rather than to fill a gap convincingly.","Prompts, tools and data sources are versioned, so a wrong answer can be traced to a change.","Confidence thresholds and a documented handover to a human are part of the design, not a later patch.","We write down, in the project documentation, the decisions the AI must never make alone."]},engagement:{eyebrow:"Commercials",heading:"How US engagements are usually structured",intro:"Three shapes cover almost every project. The right one depends on how well the scope is understood on the day you ask.",options:[{name:"Fixed-scope release",body:"A defined first release with a written scope, a milestone schedule and payments tied to those milestones. Changes are re-quoted rather than swallowed.",bestFor:"Best when the outcome is clear and the budget has to be committed in advance."},{name:"Dedicated team, monthly",body:"An agreed set of people for an agreed number of months, working a prioritised backlog you control and re-order between cycles.",bestFor:"Best for a roadmap that will change, or an ongoing second engineering team."},{name:"Assessment first, then decide",body:"A short paid assessment producing a written report: what the system does, what is wrong with it, what it would take to fix. No obligation to continue with us.",bestFor:"Best when you inherited a system and need an outside read before committing."}]},faqs:[{question:"Does SCS Softwares have a United States office?",answer:"No. We operate from Indore, India, and every United States project is delivered remotely from there. We have no US address, no US phone number and no US-registered company, and we would rather say that plainly than let a market page imply otherwise."},{question:"Can you work with a US company that has never hired offshore before?",answer:"Yes, and that is most of these engagements. The parts that make it work are unglamorous: a written scope before development, a fixed recurring meeting in your working day, a demonstrable build every cycle, and change requests priced in writing. We set all four up during discovery rather than assuming you already know how we operate."},{question:"How much overlap with US working hours can we expect?",answer:"We agree a specific recurring window with you before the project starts and staff it for your team. We deliberately do not publish a fixed number of overlap hours, because the honest answer depends on which US time zone you are in and which of our engineers your project needs."},{question:"Who owns the intellectual property?",answer:"You do. IP assignment is written into the agreement before development begins, and repositories, designs, cloud accounts and credentials are handed over at the end of the engagement. Nothing about the arrangement depends on you staying with us afterwards."},{question:"Are you HIPAA or SOC 2 compliant?",answer:"We hold no such certification and do not claim compliance with either framework. What we can do is build to the controls your compliance or security team defines — hosting region, access model, logging, retention, encryption — and document what we implemented so your auditors can assess it. If a project cannot proceed without a certified vendor, we will say so during discovery."},{question:"Which US laws apply to the contract?",answer:"That is a question for your attorney, not for us. We are an Indian company and our standard agreement reflects that, but governing law, jurisdiction and data-processing terms are negotiated per contract. We do not offer legal or tax advice for any US jurisdiction."},{question:"What does the first two weeks look like?",answer:"A framing call, then remote discovery: requirement sessions inside your working day, a written scope document with assumptions and exclusions, an estimate as a range, and agreement on hosting, access and the meeting schedule. Development starts once that document is approved — not before."}],otherMarkets:[{path:"/locations/united-kingdom",label:"United Kingdom",blurb:"The same team, a shorter time-zone gap and a delivery rhythm built around documented requirements and staged approvals."},{path:"/locations/united-arab-emirates",label:"United Arab Emirates",blurb:"Near-overlapping working days, mobile-first customer experiences, and Arabic interface work available as a scoped addition."},{path:"/locations/canada",label:"Canada",blurb:"The same continent and a different opening question: which hours we hold open, and what each milestone has to satisfy on paper."},{path:"/locations/australia",label:"Australia",blurb:"An afternoon-to-morning overlap, a test environment open throughout, and the release and support plan settled before launch."},{path:"/locations/singapore",label:"Singapore",blurb:"Head-office platforms designed for several markets at once, heavy on integrations and on a written decision trail."},{path:"/locations/germany",label:"Germany",blurb:"A market that starts from the specification: acceptance criteria written and agreed before implementation, and release evidence handed over with the build."},{path:"/locations/netherlands",label:"Netherlands",blurb:"Integration work across systems already in daily use, decided in short written notes and shown working at the end of every cycle."},{path:"/locations/turkey",label:"Turkey",blurb:"Consumer marketplaces and booking products, with each payment or messaging provider integrated as its own scoped piece of work."}],cta:{title:"Describe the build and we will tell you what it takes",body:"Answer a few questions for an indicative estimate, talk it through with our AI consultation agent, or send the requirement straight to the team in Indore. All three reach the same people."}},h=()=>e.jsx(t,{content:a(n)});export{h as default};
